int vf3_away_batch251_adapter_contains(uint32_t pc) {
pc&=0x1fffffffu; unsigned lo=0,hi=sizeof(claim_pcs)/sizeof(claim_pcs[0]);
while(lo<hi) { unsigned mid=lo+(hi-lo)/2; if(claim_pcs[mid]<pc) lo=mid+1; else hi=mid; }
return lo<sizeof(claim_pcs)/sizeof(claim_pcs[0]) && claim_pcs[lo]==pc;
}
int vf3_away_batch251_adapter(uint32_t entry,vf3_matrix_state*s,const vf3_ram_map*ram) {
if(!vf3_away_batch251_adapter_contains(entry)) { s->failed_pc=entry; return 0; }
uint32_t pc=entry&0x1fffffffu;
if(pc<=0x0c068f90u) return vf3_away_batch251_adapter_0(entry,s,ram);
if(pc<=0x0c0a7f54u) return vf3_away_batch251_adapter_1(entry,s,ram);
if(pc<=0x0c0b22acu) return vf3_away_batch251_adapter_2(entry,s,ram);
if(pc<=0x0c0bef20u) return vf3_away_batch251_adapter_3(entry,s,ram);
if(pc<=0x0c0c2244u) return vf3_away_batch251_adapter_4(entry,s,ram);
if(pc<=0x0c0c8622u) return vf3_away_batch251_adapter_5(entry,s,ram);
s->failed_pc=entry; return 0;
}
